        , cast(null as varchar) as PRODUCT_VERSION_APPLIED
        , cast(null as varchar) as ADDITIONAL_REMARKS
        , cast(null as varchar) as APPLICATION_SUBMISSION_DATE
        , cast(null as varchar) as POLICY_ISSUED_INDICATOR
        , cast(null as varchar) as CONTRACT_PARTITION_NUMBER
        , cast(null as varchar) as LOAN_CO_APPLICANT_COUNT
        , cast(null as varchar) as CO_APPLICANT_COVER_REQUESTED_INDICATOR
        , cast(null as varchar) as UNDERWRITING_REVIEW_INDICATOR
        , CUSTOMER_COMM as CUSTOMER_COMMUNICATION_TEXT
        , cast(null as varchar) as INTERNAL_TRACKING_NUMBER
        , cast(null as varchar) as PREMIUM_CALCULATION_PERIOD
        , 'BA_CCP_SUB_MATER_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_sub_mater_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , VERSION_NO as POLICY_VERSION_NUMBER
        , cast(null as varchar) as SHORT_PERIOD_END_DATE
        , cast(null as varchar) as POLICY_ISSUANCE_CONFIRMATION_INDICATOR
        , cast(null as varchar) as PRODUCT_VERSION_APPLIED
        , cast(null as varchar) as ADDITIONAL_REMARKS
        , cast(null as varchar) as APPLICATION_SUBMISSION_DATE
        , cast(null as varchar) as POLICY_ISSUED_INDICATOR
        , cast(null as varchar) as CONTRACT_PARTITION_NUMBER
        , cast(null as varchar) as LOAN_CO_APPLICANT_COUNT
        , cast(null as varchar) as CO_APPLICANT_COVER_REQUESTED_INDICATOR
        , cast(null as varchar) as UNDERWRITING_REVIEW_INDICATOR
        , cast(null as varchar) as CUSTOMER_COMMUNICATION_TEXT
        , cast(null as varchar) as INTERNAL_TRACKING_NUMBER
        , cast(null as varchar) as PREMIUM_CALCULATION_PERIOD
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , VERSION_NO as POLICY_VERSION_NUMBER
        , cast(null as varchar) as SHORT_PERIOD_END_DATE
        , cast(null as varchar) as POLICY_ISSUANCE_CONFIRMATION_INDICATOR
        , cast(null as varchar) as PRODUCT_VERSION_APPLIED
        , COMMENTS as ADDITIONAL_REMARKS
        , cast(null as varchar) as APPLICATION_SUBMISSION_DATE
        , cast(null as varchar) as POLICY_ISSUED_INDICATOR
        , cast(null as varchar) as CONTRACT_PARTITION_NUMBER
        , cast(null as varchar) as LOAN_CO_APPLICANT_COUNT
        , cast(null as varchar) as CO_APPLICANT_COVER_REQUESTED_INDICATOR
        , cast(null as varchar) as UNDERWRITING_REVIEW_INDICATOR
        , cast(null as varchar) as CUSTOMER_COMMUNICATION_TEXT
        , I_TRACK_NO as INTERNAL_TRACKING_NUMBER
        , CALCULATION_PERIOD as PREMIUM_CALCULATION_PERIOD
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then POLICY_VERSION_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then POLICY_VERSION_NUMBER end)) as POLICY_VERSION_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SHORT_PERIOD_END_DATE end) as SHORT_PERIOD_END_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then POLICY_ISSUANCE_CONFIRMATION_INDICATOR end) as POLICY_ISSUANCE_CONFIRMATION_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then PRODUCT_VERSION_APPLIED end) as PRODUCT_VERSION_APPLIED,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ADDITIONAL_REMARKS end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then ADDITIONAL_REMARKS end)) as ADDITIONAL_REMARKS,
        max(case when SOURCE_RUN = 'opus_health_v2' then APPLICATION_SUBMISSION_DATE end) as APPLICATION_SUBMISSION_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then POLICY_ISSUED_INDICATOR end) as POLICY_ISSUED_INDICATOR,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then CONTRACT_PARTITION_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then CONTRACT_PARTITION_NUMBER end)) as CONTRACT_PARTITION_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_delta3' then LOAN_CO_APPLICANT_COUNT end) as LOAN_CO_APPLICANT_COUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then CO_APPLICANT_COVER_REQUESTED_INDICATOR end) as CO_APPLICANT_COVER_REQUESTED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_delta3' then UNDERWRITING_REVIEW_INDICATOR end) as UNDERWRITING_REVIEW_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_delta3' then CUSTOMER_COMMUNICATION_TEXT end) as CUSTOMER_COMMUNICATION_TEXT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then INTERNAL_TRACKING_NUMBER end) as INTERNAL_TRACKING_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_delta3' then PREMIUM_CALCULATION_PERIOD end) as PREMIUM_CALCULATION_PERIOD,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when POLICY_VERSION_NUMBER is not null or SHORT_PERIOD_END_DATE is not null or POLICY_ISSUANCE_CONFIRMATION_INDICATOR is not null or PRODUCT_VERSION_APPLIED is not null or ADDITIONAL_REMARKS is not null or APPLICATION_SUBMISSION_DATE is not null or POLICY_ISSUED_INDICATOR is not null or CONTRACT_PARTITION_NUMBER is not null or LOAN_CO_APPLICANT_COUNT is not null or CO_APPLICANT_COVER_REQUESTED_INDICATOR is not null or UNDERWRITING_REVIEW_INDICATOR is not null or CUSTOMER_COMMUNICATION_TEXT is not null or INTERNAL_TRACKING_NUMBER is not null or PREMIUM_CALCULATION_PERIOD is not null
                     then md5(upper(coalesce(cast(POLICY_VERSION_NUMBER as varchar), '') || '|' || coalesce(cast(SHORT_PERIOD_END_DATE as varchar), '') || '|' || coalesce(cast(POLICY_ISSUANCE_CONFIRMATION_INDICATOR as varchar), '') || '|' || coalesce(cast(PRODUCT_VERSION_APPLIED as varchar), '') || '|' || coalesce(cast(ADDITIONAL_REMARKS as varchar), '') || '|' || coalesce(cast(APPLICATION_SUBMISSION_DATE as varchar), '') || '|' || coalesce(cast(POLICY_ISSUED_INDICATOR as varchar), '') || '|' || coalesce(cast(CONTRACT_PARTITION_NUMBER as varchar), '') || '|' || coalesce(cast(LOAN_CO_APPLICANT_COUNT as varchar), '') || '|' || coalesce(cast(CO_APPLICANT_COVER_REQUESTED_INDICATOR as varchar), '') || '|' || coalesce(cast(UNDERWRITING_REVIEW_INDICATOR as varchar), '') || '|' || coalesce(cast(CUSTOMER_COMMUNICATION_TEXT as varchar), '') || '|' || coalesce(cast(INTERNAL_TRACKING_NUMBER as varchar), '') || '|' || coalesce(cast(PREMIUM_CALCULATION_PERIOD as varchar), '')))
                end as SAT_POLICY_HEADER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_HEADER_HASHDIFF is not null
